CREATE TABLE ppto_producto_linea (cod_prod TEXT PRIMARY KEY, linea_origen TEXT NOT NULL);

-- Clasifica una línea de OC. Exhaustiva: toda OC cae en una línea, así el real cuadra con el panel.
CREATE FUNCTION fn_ppto_clasificar(p TEXT, camion BOOLEAN, total NUMERIC, lo TEXT)
RETURNS TEXT LANGUAGE sql IMMUTABLE AS $$
    SELECT CASE
        WHEN p LIKE 'REPNEU%' THEN 'A3'
        WHEN p LIKE 'REPMOTFIL%' OR p LIKE 'REPFIL%' OR p LIKE 'CLULUB%' OR p LIKE 'CLUGRA%' THEN 'A1'
        WHEN p LIKE 'CLU%' OR lo IN ('L01','L02') THEN 'D1'
        WHEN lo = 'L07' THEN 'B1'
        WHEN lo = 'L08' THEN 'B2'
        WHEN p = 'SERSEGMEN001' THEN 'B3'
        WHEN p LIKE 'REP%' OR p LIKE 'COM%' OR p LIKE 'REC%' OR p LIKE 'SERREP%'
             OR lo IN ('L03','L04','L05','L06') OR (camion AND p = 'SERSEGSEV002') THEN
            CASE WHEN NOT camion THEN 'A5' WHEN total >= 2500000 THEN 'A4' ELSE 'A2' END
        WHEN lo = 'L09' OR p LIKE 'AFE%' OR p LIKE 'ART%' THEN 'C1'
        WHEN lo = 'L10' OR p LIKE 'ISE%' THEN 'C2'
        WHEN lo = 'L11' THEN 'C3'
        WHEN lo = 'L12' THEN 'C4'
        WHEN lo = 'L13' THEN 'C5'
        WHEN lo = 'L15' THEN 'E1'
        WHEN lo = 'L16' OR p LIKE 'AOF%' OR p LIKE 'IAF%' THEN 'C7'
        WHEN lo IN ('L17','CAPEX') OR p LIKE 'EQU%' THEN 'C8'
        ELSE 'C6'
    END
$$;

CREATE VIEW v_ppto_real AS
SELECT v.fecha, v.codi_cc, c.activo_id, v.cod_prod, v.des_prod, v.total, v.folio, v.origen,
       fn_ppto_clasificar(v.cod_prod, c.activo_id IS NOT NULL, v.total, m.linea_origen) AS linea
  FROM v_costos_linea v
  LEFT JOIN softland_cc c ON c.codigo = v.codi_cc
  LEFT JOIN ppto_producto_linea m ON m.cod_prod = v.cod_prod
 WHERE v.fuente = 'oc' AND NOT v.es_mercaderia AND v.fecha >= DATE '2023-01-01';

CREATE TABLE ppto_kit_item (
    id BIGSERIAL PRIMARY KEY,
    grupo_kit TEXT NOT NULL,
    nivel TEXT NOT NULL,
    item TEXT NOT NULL,
    cantidad NUMERIC NOT NULL,
    unidad TEXT,
    cod_softland TEXT,
    precio_ref NUMERIC NOT NULL,
    precio_vivo BOOLEAN NOT NULL,   -- true: se actualiza con la compra real de Softland
    fil_lub BOOLEAN NOT NULL        -- true: filtro o lubricante (lo demás ya está en el correctivo real)
);
CREATE INDEX ON ppto_kit_item (grupo_kit, nivel);

CREATE TABLE ppto_modelo_grupo (modelo TEXT PRIMARY KEY, grupo_kit TEXT NOT NULL, intervalo_horas INT NOT NULL);
