CREATE TABLE ppto_programa (
    id BIGSERIAL PRIMARY KEY,
    anio INT NOT NULL CHECK (anio BETWEEN 2027 AND 2029),
    tipo TEXT NOT NULL CHECK (tipo IN ('opex','capex','overhaul')),
    patente TEXT,
    descripcion TEXT NOT NULL,
    monto NUMERIC NOT NULL CHECK (monto >= 0),
    gatillo TEXT,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by UUID
);
