CREATE TABLE ppto_version (
    id BIGSERIAL PRIMARY KEY,
    nombre TEXT NOT NULL,
    congelada BOOLEAN NOT NULL DEFAULT false,
    calculado_at TIMESTAMPTZ,
    calculado_por UUID,
    meta JSONB
);
INSERT INTO ppto_version (id,nombre) VALUES (1,'Trabajo');
SELECT setval(pg_get_serial_sequence('ppto_version','id'), 1);

CREATE TABLE ppto_resultado (
    version_id BIGINT NOT NULL REFERENCES ppto_version(id) ON DELETE CASCADE,
    anio INT NOT NULL,
    mes INT,          -- NULL: se reparte parejo en el año
    linea TEXT NOT NULL REFERENCES ppto_linea(codigo),
    patente TEXT,
    descripcion TEXT,
    monto NUMERIC NOT NULL
);
CREATE INDEX ON ppto_resultado (version_id, anio, linea);

CREATE TABLE ppto_base (linea TEXT PRIMARY KEY REFERENCES ppto_linea(codigo), base_anual NUMERIC NOT NULL);

CREATE TABLE ppto_camion (
    patente TEXT PRIMARY KEY, activo_id UUID, modelo TEXT, anio_fab INT, estado_comercial TEXT,
    faena TEXT, grupo_kit TEXT, horometro NUMERIC, ritmo NUMERIC, ritmo_fuente TEXT,
    base_correctivo NUMERIC, base_neumatico NUMERIC
);

CREATE TABLE ppto_visita (
    id BIGSERIAL PRIMARY KEY, patente TEXT NOT NULL, fecha DATE NOT NULL, anio INT NOT NULL, mes INT NOT NULL,
    horas NUMERIC, nivel TEXT NOT NULL, tipo TEXT NOT NULL,
    costo NUMERIC NOT NULL,      -- lo que entra a la línea (filtros y lubricantes; componente completo)
    costo_kit NUMERIC NOT NULL   -- kit completo, para planificar la compra
);
CREATE INDEX ON ppto_visita (anio, mes);

ALTER TABLE ppto_linea ENABLE ROW LEVEL SECURITY;
ALTER TABLE ppto_producto_linea ENABLE ROW LEVEL SECURITY;
ALTER TABLE ppto_kit_item ENABLE ROW LEVEL SECURITY;
