ALTER TABLE ppto_curva_edad ENABLE ROW LEVEL SECURITY;
ALTER TABLE ppto_supuesto ENABLE ROW LEVEL SECURITY;
ALTER TABLE ppto_flota_ajuste ENABLE ROW LEVEL SECURITY;
ALTER TABLE ppto_programa ENABLE ROW LEVEL SECURITY;
